// Escolhe quem deve receber atualização: tem consentimento, processo em andamento
// e está há UPDATE_INTERVAL_DAYS dias (padrão 3) ou mais sem contato.
const fs = require('fs');
const cands = JSON.parse(fs.readFileSync('/files/candidatos.json', 'utf8'));
const dias = Number($env.UPDATE_INTERVAL_DAYS || 3);
const agora = Date.now();
const ETAPAS_FINAIS = ['Contratado', 'Reprovado', 'Desistiu'];
const template = $env.WA_TEMPLATE_UPDATE || 'hello_world';

const devidos = cands.filter((c) => {
  if (!c.consentimento_whatsapp) return false;
  if (ETAPAS_FINAIS.includes(c.etapa)) return false;
  if (!c.ultimo_contato) return true;
  return (agora - new Date(c.ultimo_contato).getTime()) / 86400000 >= dias;
});

return devidos.map((c) => ({ json: {
  id: c.id,
  nome: c.nome,
  payload: {
    messaging_product: 'whatsapp',
    to: c.telefone,
    type: 'template',
    template: template === 'hello_world'
      // Template de teste que já vem aprovado no número de teste da Meta
      ? { name: 'hello_world', language: { code: 'en_US' } }
      // Seu template aprovado: {{1}} nome, {{2}} vaga, {{3}} etapa
      : { name: template, language: { code: 'pt_BR' }, components: [{ type: 'body', parameters: [
          { type: 'text', text: c.nome.split(' ')[0] },
          { type: 'text', text: c.vaga },
          { type: 'text', text: c.etapa },
        ] }] },
  },
} }));

// Grava a data do último contato de quem recebeu com sucesso
const fs = require('fs');
const ARQ = '/files/candidatos.json';
const enviados = $('Selecionar candidatos').all();
const respostas = $input.all();

const ok = new Set();
const falhas = [];
respostas.forEach((r, i) => {
  if (r.json.messages) ok.add(enviados[i].json.id);
  else falhas.push({ candidato: enviados[i].json.nome, erro: r.json.error || r.json });
});

const cands = JSON.parse(fs.readFileSync(ARQ, 'utf8'));
const agora = new Date().toISOString();
cands.forEach((c) => { if (ok.has(c.id)) c.ultimo_contato = agora; });
fs.writeFileSync(ARQ, JSON.stringify(cands, null, 2));

return [{ json: { enviados: ok.size, falhas } }];
